import sys
import json
import os

RULE_FACT_FIELD = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", True),
        "classification date": ("fda_enforcement_reports", "center_classification_date", True),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", True),
        "termination date": ("fda_enforcement_reports", "termination_date", True),
    },
}

def format_date(val):
    if not val:
        return None
    val = str(val).strip()
    if not val:
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    return val

def load_data(packet_dir):
    data_files = {}
    reports_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    if os.path.exists(reports_path):
        with open(reports_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            data_files["fda_enforcement_reports"] = data.get("results", [])
    else:
        data_files["fda_enforcement_reports"] = []
    return data_files

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    data_files = load_data(packet_dir)

    # Index fda_enforcement_reports by recall_number
    by_recall_number = {}
    for item in data_files.get("fda_enforcement_reports", []):
        r_num = item.get("recall_number")
        if r_num:
            by_recall_number.setdefault(r_num, []).append(item)

    pairs = manifest.get("pairs", [])
    manifest_facts = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts_list = manifest_facts.get(rule_id, [])
        output[pair] = {}

        rule_mapping = RULE_FACT_FIELD.get(rule_id, {})

        for fact in facts_list:
            if fact not in rule_mapping:
                output[pair][fact] = "ABSENT"
                continue

            doc_name, field_name, is_date = rule_mapping[fact]

            if doc_name == "fda_enforcement_reports":
                matching_records = by_recall_number.get(entity, [])
                values = set()
                for rec in matching_records:
                    raw_val = rec.get(field_name)
                    if is_date:
                        val = format_date(raw_val)
                    else:
                        val = str(raw_val).strip() if raw_val is not None and str(raw_val).strip() else None

                    if val is not None:
                        values.add(val)

                if len(values) == 0:
                    output[pair][fact] = "ABSENT"
                elif len(values) == 1:
                    output[pair][fact] = [next(iter(values)), doc_name]
                else:
                    output[pair][fact] = "CONFLICT"
            else:
                output[pair][fact] = "ABSENT"

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()
