import sys
import os
import json
import re
from datetime import datetime

FIELD_MAP = {
    "initiation date": "recall_initiation_date",
    "classification date": "center_classification_date",
    "termination date": "termination_date"
}

def format_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None
    if re.match(r'^\d{8}$', val):
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    if re.match(r'^\d{4}-\d{2}-\d{2}$', val):
        return val
    for fmt in ('%Y/%m/%d', '%m/%d/%Y', '%Y-%m-%d'):
        try:
            dt = datetime.strptime(val, fmt)
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            pass
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    enforcement_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    doc_name = "fda_enforcement_reports"

    records_by_recall_number = {}
    if os.path.exists(enforcement_file):
        with open(enforcement_file, 'r', encoding='utf-8') as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                rn = item.get("recall_number")
                if rn:
                    records_by_recall_number.setdefault(rn, []).append(item)

    output = {}
    facts_config = manifest.get("facts", {})
    pairs = manifest.get("pairs", [])

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        facts = facts_config.get(rule_id, [])
        output[pair] = {}

        matching_records = records_by_recall_number.get(entity, [])

        for fact in facts:
