    doc_path = None
    for p in packet_dir.iterdir():
        if p.stem == "fda_enforcement_reports" and p.suffix.lower() == ".json":
            doc_path = p
            break
    if doc_path is None:
        for p in packet_dir.rglob("fda_enforcement_reports.json"):
            doc_path = p
            break

    records_by_recall_number = {}
    if doc_path and doc_path.is_file():
        with open(doc_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            results = data.get("results", [])
            if not isinstance(results, list):
                results = [data]
        elif isinstance(data, list):
            results = data
        else:
            results = []

        for rec in results:
            if isinstance(rec, dict) and "recall_number" in rec:
                rn = rec["recall_number"]
                records_by_recall_number.setdefault(rn, []).append(rec)

    pairs = manifest.get("pairs", [])
    facts_config = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity_id = pair.split("::", 1)
        else:
            rule_id, entity_id = pair, ""

        pair_result = {}
