import sys
import os
import json
import re

FACT_MAPPINGS = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", "date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date", "date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", "date"),
        "termination date": ("fda_enforcement_reports", "termination_date", "date"),
    },
}

def format_date(val):
    if not val:
        return None
    val_str = str(val).strip()
    if not val_str or val_str.upper() in ("N/A", "NONE", "NULL"):
        return None
    if len(val_str) == 8 and val_str.isdigit():
        return f"{val_str[:4]}-{val_str[4:6]}-{val_str[6:]}"
    if re.match(r"^\d{4}-\d{2}-\d{2}$", val_str):
        return val_str
    return val_str

def load_json_records(filepath):
    if not os.path.exists(filepath):
        return []
    with open(filepath, "r", encoding="utf-8") as f:
        data = json.load(f)
    if isinstance(data, dict):
        return data.get("results", [])
    if isinstance(data, list):
        return data
    return []

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

